WFJ.Data.add("quest", {
  [90116] = { "聖なる糸", "Crusader's Loomのすぐ近くで布を織って反物にし、Dawnwoven Fabricsを手に入れる。十分な量が集まったらTaylorのところへ戻って下さい。", "この機は特別なのです。ご存じでしたか？私たちの職人はみな、仕事道具を高位のプリーストたちに祝福してもらったのです。\n\nとりわけこの機は、最も神聖な儀式用の祭服に使われる運命にある、はぐれた布や糸を引き寄せます。時が経てば新しいローブを作るのに十分な量が集まります。そうした日々は祝いの種なのです。少なくとも私にとっては。\n\nご自身の好奇心からこの過程に興味がおありなら、機の近くで布地を何反か糸に通して、光の働きをご覧になってください。", nil, nil, 0xc5231693, 0x64619cbd, 0x049e6b14, nil, nil, "...mm" },
  [90487] = { "古き盟友", "隠者の洞窟から西へ進み、Mount Hyjalの低い斜面にある古代樹とドライアドの前哨地を見つけてください。", "{name}、私にはもうお伝えできることはあまりありません。山を登る長い道のりに挑むつもりなら、古くからの山の守り手たちと話してみるとよいでしょう。\n\n西へ道をたどり、北の山のふもとの方を見てください。やがて前哨地が見えてきます。かつて斜面を歩き回っていた守護者たちの名残です。そこにFraxinusという古の存在がいます。彼とその友人たちがあなたを助けてくれるでしょう。", nil, nil, 0x00eda785, 0xe01cf952, 0x868ea2c2, nil, nil, "...mm" },
  [90647] = { "Staff of the Mountain", "Staff of the MountainをSummit of EternityにいるTiala Whitemaneのところへ持って行ってください。", "あなたが集めてくれた材料のおかげで、取り戻してくれた杖に新たな魔法を注ぎ込むことができました。これで、Ve'hanが大胆にも盗んだWild Godsの魔法を打ち消すのに、この力を使えるはずです。\n\nただし、試してみる必要があります。これをSummit of EternityにいるTiala Whitemaneという名のドルイドのもとへ持って行ってください。彼女が力になってくれるかもしれません。", nil, nil, 0x9af96789, 0x16e85ed9, 0x964a463f, nil, nil, "...mm" },
  [90702] = { "荒らされた墓", "辺りを探して、墓からなくなった中身を見つけてください。", "<何者か、あるいは何かが土を掘り返し、骨のかけらをあちこちに散らかしている。奇妙な形のくぼみが、冷たく湿った土の奥へと続いている。\n\nこの辺りの何かが、この騒ぎを引き起こしたのかもしれない。>", nil, nil, 0x122854ff, 0xee590106, 0x0c5c29bc, nil, nil, "...mm" },
  [90750] = { "まだ仕事が？", "農民と話し、仕事が終わったことを知らせてください。", "戦いというものは、たいてい長く苛烈なものだ。差し迫った脅威に立ち向かい、死を正面から見据える覚悟のある者たちが率いる。\n\n実のところ、多くの犠牲が払われたのは戦場だけではない。我々は、自分の役目を果たして貢献してくれる者たちを見落としがちだ。\n\nすぐそこにいる農夫の名は……いや、考えてみれば、名前すら知らないな。私はなんという人間だ？彼は我々の滞在中ずっと、我々の世話をし、食事を用意してくれた。\n\n彼と話してくれないか？仕事は終わったと伝えてやってくれ。", nil, nil, 0x4489f9ed, 0x38a33249, 0x28f0afda, nil, nil, "...mm" },
  [90789] = { "Scalebeard", "Archmage XylemのためにPrismatic Shellを取ってきてください。大魔道士はAzsharaの崖の上の塔に住んでいます。", "時間がないのだ、{name}！私の占いの呪文が、強力な魔力の源を明らかにした。私は塔を離れられない。この遺物を持つ邪悪な生き物を倒してきてほしい。\n\nその獣はScalebeardと呼ばれ、Bay of Stormsの洞窟に潜んでいる。奴を焼き尽くして灰にし、その巣からprismatic shellを奪ってくるのだ。", nil, nil, 0xcd852ff9, 0xe0e3c89c, 0x86fd647a, nil, nil, "...mm" },
  [90813] = { "大当たり！", "Humongous Crystalを鑑定してくれる人を見つけてください。", "<この大きな水晶の塊は、見た目以上に重い。かなりの値打ち物に見えるが、その本当の正体はわからない。地質学の知識がある者なら、本当は何を見つけたのか教えてくれるだろう。>", nil, nil, 0x89afa7ee, 0x45a72cf5, 0x055b1f5b, nil, nil, "...mm" },
  [90854] = { "悪天候に備える革", "Rugged Armor Kitを$N1個とCured Rugged Hideを$N2枚、Mount HyjalのElderwildにいるZet'ganのところへ持って行ってください。", "5年も野生で暮らしてりゃ、物資もすっかり減っちまう。この場所は一から作らなきゃならなかったんだ！あんたの革細工職人としての腕を借りたいぜ。\n\nテントや建物をいくつか修理して、鎧も繕わなきゃならねえ。Rugged Armor Kitsを一組とCured Rugged Hideを持ってきてくれりゃ、そいつを特別なもんに変える手伝いをしてやるよ。", nil, nil, 0x8cba0394, 0x1cb3933a, 0xe948817e, nil, nil, "...mm" },
  [90865] = { "見張りの目", "Elunethのために、Watcher's Eyeを$N1個取ってきてください。", "ここからすぐ北に、過去の戦いの廃墟がある。衰えつつあるscourgeの勢力がまだ残っている。\n\n心なきアンデッドもそれ自体が脅威だが、見張り役たちがこの地に入る者に油断なく目を光らせているせいで、scourgeの脅威を取り除くことがさらに難しくなっている。\n\n見張り役たちが最も大切にしているものを奪い取って、その脅威を取り除いてくれ。", nil, nil, 0x00105bc6, 0x90eb674f, 0x50a79b26, nil, nil, "...mm" },
  [90902] = { "光の再発見", "Holy Lightの能力でInjured Deathguardを$N1人治療してください。", "新たに蘇ったパラディンを我らの仲間に迎えられることを誇りに思います。光とのつながりを取り戻し始めると、かつては自然にできていた能力の一部が、今は使うと相当な苦痛を伴うことに気づくかもしれません。特に、光を導いて自分や他者を癒やす能力がそうです。\n\nこの問題を避ける唯一の方法は――残念ながら――それを乗り越えることです。衰えた他の筋肉と同じように、痛みを押して肉体を鍛え、完全な機能を取り戻さねばなりません。", "光を極める力は、時が経てば戻ってくるでしょう。", "死を耐え抜いた者にとって、痛みは目新しいものではありません。だからこそForsakenは痛みにとりわけ強いのです。痛みには浄化の力もあります。それを名誉の証として、そして新たな境遇にあってもなお、あなたが光の僕であるという証拠として受け入れるべきです。\n\n健やかに、そして再び光の中を歩みなさい、{class}。", 0xd0181974, 0x52f98d38, 0xcb54b8cd, 0x89566d7b, 0x32977739, "....." },
